        /// Regions to check from, as any combination of 'us', 'eu', 'as' and 'au'. When none are set, we check from all regions. Responses then list all of them.
        /// </summary>
        public InputList<string> Regions
        {
            get => _regions ?? (_regions = new InputList<string>());
            set => _regions = value;
        }

        /// <summary>
        /// Whether we keep cookies when redirecting. Defaults to true.
        /// </summary>
        [Input("rememberCookies")]
        public Input<bool>? RememberCookies { get; set; }

        /// <summary>
        /// The body of the request. A 'dns' monitor requires it. Set it to the domain to query. A 'udp' monitor sends it as its content. Must be empty for 'get', 'head' and 'options' requests.
        /// </summary>
        [Input("requestBody")]
        public Input<string>? RequestBody { get; set; }

        [Input("requestHeaders")]
        private InputList<Inputs.MonitorRequestHeaderGetArgs>? _requestHeaders;

        /// <summary>
        /// Custom request headers, as a list of `{name, value}` objects. A list replaces all headers, and an empty list removes them all.
        /// </summary>
        public InputList<Inputs.MonitorRequestHeaderGetArgs> RequestHeaders
        {
            get => _requestHeaders ?? (_requestHeaders = new InputList<Inputs.MonitorRequestHeaderGetArgs>());
            set => _requestHeaders = value;
        }

        /// <summary>
        /// How long a check waits before it times out. Its unit and accepted values depend on `MonitorType`. `Status`, 'expected_status_code', 'keyword' and 'keyword_absence': In seconds. It accepts '2', '3', '5', '10', '15', '30', '45', '60', '90', '120' or '180' and defaults to '30'. 'ping', 'tcp', 'udp', 'smtp', 'pop', 'imap' and 'dns': In milliseconds. It accepts '500', '1000', '2000', '3000' or '5000' and defaults to '5000'. 'playwright': In seconds. It accepts '15', '30', '45', '60', '120', '180', '240', '300', '360', '480', '600' or '900' and defaults to '30'.
        /// </summary>
        [Input("requestTimeout")]
        public Input<int>? RequestTimeout { get; set; }

        /// <summary>
        /// The keyword to look for. Required for 'keyword', 'keyword_absence' and 'udp' monitors.
        /// </summary>
        [Input("requiredKeyword")]
        public Input<string>? RequiredKeyword { get; set; }

        /// <summary>
        /// The name of a 'playwright' monitor's scenario. Required for 'playwright' monitors, and returned only for them. At least one of `Url` or `ScenarioName` must be configured.
        /// </summary>
        [Input("scenarioName")]
        public Input<string>? ScenarioName { get; set; }

        /// <summary>
        /// Whether to send an SMS to the on-call person. Ignored while an escalation policy is set. Defaults to false.
        /// </summary>
        [Input("sms")]
        public Input<bool>? Sms { get; set; }

        /// <summary>
        /// How many days before the SSL certificate expires we alert you. null turns the check off and is the default. Monitors of exactly the same domain share this setting, not its subdomains. For example, monitors of `example.com/a` and `example.com/b` share it, while `www.example.com` has its own. A value set on one monitor is copied to all of them, so set the same value on each. Valid values: '1', '2', '3', '7', '14', '30', '60'.
        /// </summary>
        [Input("sslExpiration")]
        public Input<int>? SslExpiration { get; set; }

        /// <summary>
        /// The monitor's current status. 'up': Checks pass. 'down': Checks fail. 'validating': The service seems back up, but the `RecoveryPeriod` hasn't passed yet. `Paused`: The monitor is paused. 'pending': The monitor waits for its first check. 'maintenance': The monitor is in a maintenance window.
        /// </summary>
        [Input("status")]
        public Input<string>? Status { get; set; }

        /// <summary>
        /// Team that owns this monitor, such as 't123'. Defaults to the provider's `TeamId`. Set it to create this object in another team. Changing it replaces the resource, because an object can't move to another team.
        /// </summary>
        [Input("teamId")]
        public Input<string>? TeamId { get; set; }

        /// <summary>
        /// Name of the team that owns this monitor.
        /// </summary>
        [Input("teamName")]
        public Input<string>? TeamName { get; set; }

        /// <summary>
        /// Seconds to wait before escalating to the whole team. '0' alerts the whole team right away, and null never escalates to the team. Ignored while an escalation policy is set.
        /// </summary>
        [Input("teamWait")]
        public Input<int>? TeamWait { get; set; }

        /// <summary>
        /// When the monitor was last updated.
        /// </summary>
        [Input("updatedAt")]
        public Input<string>? UpdatedAt { get; set; }

        /// <summary>
        /// The URL of your website, or the host to check for 'ping', 'tcp', 'udp', 'smtp', 'pop', 'imap' and 'dns' monitors, without a protocol. It's null on 'playwright' monitors. Required for every type except 'playwright', which accepts `ScenarioName` instead. At least one of `Url` or `ScenarioName` must be configured.
        /// </summary>
        [Input("url")]
        public Input<string>? Url { get; set; }

        /// <summary>
        /// Whether a check fails on an invalid SSL certificate. Defaults to true.
        /// </summary>
        [Input("verifySsl")]
        public Input<bool>? VerifySsl { get; set; }

        public MonitorState()
        {
        }
        public static new MonitorState Empty => new MonitorState();
    }
}
